using Astrea;
using NaughtyAttributes;
using UnityEngine;

namespace LittleLeo.Variables;

[CreateAssetMenu(menuName = "Variables References/ZoomableInstance Reference")]
public class ZoomableInstanceReference : ScriptableObject
{
	[Header("Variable")]
	[SerializeField]
	private bool externalSet;

	[SerializeField]
	[HideIf("externalSet")]
	private ZoomableInstance value;

	[Header("Debug")]
	[SerializeField]
	private bool verbose;

	public ZoomableInstance Value => value;

	public void SetExternalSet(bool value)
	{
		externalSet = value;
	}

	public void SetValue(ZoomableInstance value)
	{
		if (externalSet)
		{
			this.value = value;
		}
	}
}
